mapper.delete:
DELETE FROM node
WHERE id IN

    #{id}

mapper.select:
SELECT 
FROM node
WHERE 
        parent_id = #{parentId}


        parent_id IS NULL

      AND `name` = #{name}

SELECT FROM node WHERE
parent_id = #{parentId}
parent_id IS NULL

WITH RECURSIVE descendants AS (
    SELECT id FROM node WHERE id = #{id}
    UNION ALL
    SELECT n.id FROM node n JOIN descendants d ON n.parent_id = d.id
)
SELECT id FROM descendants WHERE id != #{id};

SELECT , mt.name AS mime_type_name FROM node n LEFT JOIN mime_types mt ON n.mime_type_id = mt.id WHERE
n.parent_id = #{parentId}
n.parent_id IS NULL

WITH RECURSIVE path_cte AS ( -- 锚点: 找到路径的第一部分对应的顶级节点 (parent_id is null) SELECT id, 1 AS path_level FROM node WHERE parent_id IS NULL AND name = SUBSTRING_INDEX(TRIM(LEADING '/' FROM #{path}), '/', 1)
UNION ALL
-- 递归: 逐级向下查找子节点 SELECT n.id, pc.path_level + 1 FROM node n JOIN path_cte pc ON n.parent_id = pc.id WHERE n.name = SUBSTRING_INDEX(SUBSTRING_INDEX(TRIM(LEADING '/' FROM #{path}), '/', pc.path_level + 1), '/', -1) ) SELECT n.id, n.parent_id, n.name, n.type, n.size, n.create_time, n.modify_time, n.hash_id, n.mime_type_id FROM node n JOIN path_cte pc ON n.id = pc.id WHERE pc.path_level = (LENGTH(#{path}) - LENGTH(REPLACE(#{path}, '/', ''))) LIMIT 1;

WITH RECURSIVE path_cte AS ( -- 锚点: 找到路径的第一部分对应的顶级节点 (parent_id is null) SELECT id, 1 AS path_level FROM node WHERE parent_id IS NULL AND name = SUBSTRING_INDEX(TRIM(LEADING '/' FROM #{path}), '/', 1)
UNION ALL
-- 递归: 逐级向下查找子节点 SELECT n.id, pc.path_level + 1 FROM node n JOIN path_cte pc ON n.parent_id = pc.id WHERE n.name = SUBSTRING_INDEX(SUBSTRING_INDEX(TRIM(LEADING '/' FROM #{path}), '/', pc.path_level + 1), '/', -1) ) SELECT n.id, n.parent_id, n.name, n.type, n.size, n.create_time, n.modify_time, n.hash_id, n.mime_type_id, mt.name AS mime_type_name FROM node n JOIN path_cte pc ON n.id = pc.id LEFT JOIN mime_types mt ON n.mime_type_id = mt.id WHERE pc.path_level = (LENGTH(#{path}) - LENGTH(REPLACE(#{path}, '/', ''))) LIMIT 1;
